import React, { useMemo, useState } from "react";
import "./ClientsList.css";

const Clients = [
  {
    id: 1,
    title: "Empresa A",
    invoices: [
      { id: 1, date: "2026-06-10", amount: 500 },
      { id: 2, date: "2026-06-20", amount: 800 },
    ],
  },
  {
    id: 2,
    title: "Empresa B",
    invoices: [
      { id: 3, date: "2026-05-15", amount: 300 },
      { id: 4, date: "2026-06-25", amount: 700 },
    ],
  },
  {
    id: 3,
    title: "Empresa C",
    invoices: [
      { id: 5, date: "2026-06-05", amount: 1200 },
      { id: 6, date: "2026-07-01", amount: 900 },
    ],
  },
];

const ClientsList = () => {
  const [query, setQuery] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [compareWith, setCompareWith] = useState("");
  const [showFilters, setShowFilters] = useState(true);

  const filteredClients = useMemo(() => {
    return Clients.filter((client) => {
      const matchesName = client.title
        .toLowerCase()
        .includes(query.toLowerCase());

      const matchesDate =
        !dateFrom ||
        !dateTo ||
        client.invoices.some((invoice) => {
          const invoiceDate = new Date(invoice.date);

          return (
            invoiceDate >= new Date(dateFrom) &&
            invoiceDate <= new Date(dateTo)
          );
        });

      return matchesName && matchesDate;
    });
  }, [query, dateFrom, dateTo]);

  const calculateTotal = (invoices) => {
    return invoices.reduce(
      (total, invoice) => total + invoice.amount,
      0
    );
  };

  const getComparisonLabel = () => {
    switch (compareWith) {
      case "previousMonth":
        return "Comparando con mes anterior";
      case "previousYear":
        return "Comparando con año anterior";
      default:
        return null;
    }
  };

  return (
    <div className="clients-container">
      <h2 className="title">Clientes</h2>

      <div className="search-container">
        <input
          type="text"
          placeholder="Buscar un cliente..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="search-input"
        />

        <button
          className="filter-toggle"
          onClick={() => setShowFilters(!showFilters)}
        >
          ⚙
        </button>
      </div>

      {showFilters && (
        <div className="filters-panel">
          <label>📅 Rango de fechas</label>

          <div className="date-row">
            <input
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
            />

            <input
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
            />
          </div>

          <label>📊 Comparar con</label>

          <select
            value={compareWith}
            onChange={(e) => setCompareWith(e.target.value)}
          >
            <option value="">Sin elegir</option>
            <option value="previousMonth">
              Mes anterior
            </option>
            <option value="previousYear">
              Año anterior
            </option>
          </select>

          {compareWith && (
            <p className="compare-text">
              {getComparisonLabel()}
            </p>
          )}
        </div>
      )}

      <div className="clients-list">
        {filteredClients.length === 0 ? (
          <p>No existen clientes con esos filtros.</p>
        ) : (
          filteredClients.map((client) => (
            <div
              key={client.id}
              className="client-card"
            >
              <div className="client-header">
                <span>{client.title}</span>

                <button className="client-filter-btn">
                  Filtro
                </button>
              </div>

              <div className="client-info">
                <p>
                  Facturas: {client.invoices.length}
                </p>

                <p>
                  Total: $
                  {calculateTotal(client.invoices)}
                </p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ClientsList;
